def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]

    # Use the longest aligned pair as the main line.
    best = None
    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            if r1 == r2:
                candidate = (abs(c2 - c1), "h", r1, min(c1, c2), max(c1, c2))
            elif c1 == c2:
                candidate = (abs(r2 - r1), "v", c1, min(r1, r2), max(r1, r2))
            else:
                continue
            if best is None or candidate[0] > best[0]:
                best = candidate

    if best is None:
        return out

    _, direction, fixed, start, end = best
    if direction == "h":
        for c in range(start, end + 1):
            if out[fixed][c] == 0:
                out[fixed][c] = 3
        for r, c in points:
            for rr in range(min(r, fixed), max(r, fixed) + 1):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    else:
        for r in range(start, end + 1):
            if out[r][fixed] == 0:
                out[r][fixed] = 3
        for r, c in points:
            for cc in range(min(c, fixed), max(c, fixed) + 1):
                if out[r][cc] == 0:
                    out[r][cc] = 3

    return out
